/* Create Tables */

CREATE TABLE actividades
(
	id_actividad serial NOT NULL,
	codigo varchar(20) NOT NULL,
	nombre varchar(60) NOT NULL,
	descripcion varchar(255) NULL,
	modalidad varchar(13) NOT NULL,
	cupo_maximo smallint NULL,	-- > 0; obligatorio si PERSONALIZADA
	requiere_medidas boolean NOT NULL,	-- default false; peso y talla al pre-inscribir
	activo boolean NOT NULL
)
;

CREATE TABLE alumno_insignias
(
	id_alumno integer NOT NULL,
	id_insignia integer NOT NULL,
	fecha_obtencion timestamp without time zone NOT NULL
)
;

CREATE TABLE alumnos
(
	id_alumno serial NOT NULL,
	id_usuario integer NOT NULL,
	id_usuario_responsable integer NULL,	-- tutor; obligatorio si es menor
	cont_emerg_nombre varchar(80) NULL,
	cont_emerg_telefono varchar(20) NULL,
	apto_medico boolean NOT NULL,	-- default false
	fecha_apto_medico date NULL,
	observaciones varchar(500) NULL,
	estado varchar(8) NOT NULL,
	fecha_alta timestamp without time zone NOT NULL,
	fecha_baja timestamp without time zone NULL
)
;

CREATE TABLE asistencias
(
	id_clase integer NOT NULL,
	id_alumno integer NOT NULL,
	id_inscripcion integer NOT NULL,
	asistio boolean NOT NULL,
	fecha_registro timestamp without time zone NOT NULL,
	id_usuario_registra integer NULL,	-- NULL si lo registro el cierre automatico
	observaciones varchar(255) NULL
)
;

CREATE TABLE clases
(
	id_clase serial NOT NULL,
	id_horario integer NOT NULL,
	fecha_clase date NOT NULL,
	id_prof_dictante integer NOT NULL,
	estado varchar(10) NOT NULL,
	fecha_cierre_asist timestamp without time zone NULL,
	observaciones varchar(255) NULL
)
;

CREATE TABLE cuotas
(
	id_cuota serial NOT NULL,
	id_inscripcion integer NOT NULL,
	numero_cuota smallint NOT NULL,	-- >= 1
	fecha_generacion timestamp without time zone NOT NULL,
	fecha_vencimiento date NOT NULL,
	monto NUMERIC(10,2) NOT NULL	-- >= 0
)
;

CREATE TABLE horarios
(
	id_horario serial NOT NULL,
	id_actividad integer NOT NULL,
	id_profesora integer NOT NULL,
	dia_semana smallint NOT NULL,	-- 1=Lun .. 7=Dom
	hora_inicio time without time zone NOT NULL,
	hora_fin time without time zone NOT NULL,	-- > hora_inicio
	cupo_maximo smallint NULL,	-- > 0; NULL = toma el de la actividad
	fecha_alta date NOT NULL,
	fecha_baja date NULL
)
;

CREATE TABLE inscripcion_horarios
(
	id_inscripcion integer NOT NULL,
	id_horario integer NOT NULL,
	fecha_desde date NOT NULL,
	fecha_hasta date NULL
)
;

CREATE TABLE inscripciones
(
	id_inscripcion serial NOT NULL,
	id_alumno integer NOT NULL,
	id_plan integer NOT NULL,
	id_plan_precio integer NOT NULL,
	id_profesora integer NOT NULL,	-- profesora a cargo
	id_promocion integer NULL,
	sin_cargo boolean NOT NULL,	-- true: profesora que entrena; no genera honorarios
	fecha_inicio date NOT NULL,
	fecha_fin_estimado date NULL,
	estado varchar(12) NOT NULL,
	motivo_baja varchar(11) NULL,	-- obligatorio si BAJA
	observaciones varchar(500) NULL,
	fecha_alta timestamp without time zone NOT NULL,
	fecha_baja timestamp without time zone NULL
)
;

CREATE TABLE insignias
(
	id_insignia serial NOT NULL,
	codigo varchar(30) NOT NULL,
	nombre varchar(60) NOT NULL,
	descripcion varchar(255) NULL,
	tipo_criterio varchar(19) NOT NULL,
	valor_umbral smallint NOT NULL	-- > 0
)
;

CREATE TABLE liquidacion_detalles
(
	id_liq_detalle serial NOT NULL,
	id_liquidacion integer NOT NULL,
	id_tarifa integer NOT NULL,
	concepto varchar(18) NOT NULL,
	id_inscripcion integer NULL,	-- obligatorio si ALUMNO_A_CARGO
	id_clase integer NULL,	-- obligatorio si CLASE_SUPLIDA / DESCUENTO_AUSENCIA
	monto NUMERIC(10,2) NOT NULL	-- < 0 si DESCUENTO_AUSENCIA
)
;

CREATE TABLE liquidaciones
(
	id_liquidacion serial NOT NULL,
	id_profesora integer NOT NULL,
	periodo_desde date NOT NULL,
	periodo_hasta date NOT NULL,	-- > periodo_desde
	fecha_liquidacion timestamp without time zone NOT NULL,
	monto_total NUMERIC(12,2) NOT NULL,
	estado varchar(8) NOT NULL
)
;

CREATE TABLE medidas_corporales
(
	id_registro integer NOT NULL,
	id_tipo_medida integer NOT NULL,
	valor NUMERIC(6,2) NOT NULL	-- > 0
)
;

CREATE TABLE notificaciones
(
	id_notificacion serial NOT NULL,
	id_usuario integer NOT NULL,
	tipo varchar(16) NOT NULL,
	id_cuota integer NULL,	-- solo avisos de cuota
	mensaje varchar(1000) NOT NULL,
	fecha_generacion timestamp without time zone NOT NULL,
	fecha_envio timestamp without time zone NULL,
	estado_envio varchar(9) NOT NULL,
	leida boolean NOT NULL
)
;

CREATE TABLE pagos
(
	id_pago serial NOT NULL,
	id_cuota integer NOT NULL,
	forma_pago varchar(13) NOT NULL,
	estado varchar(10) NOT NULL,
	monto NUMERIC(10,2) NOT NULL,	-- > 0
	fecha_pago timestamp without time zone NOT NULL,
	titular_cuenta_origen varchar(80) NULL,	-- solo TRANSFERENCIA
	fecha_hora_transferencia timestamp without time zone NULL,	-- solo TRANSFERENCIA
	id_usuario_registra integer NOT NULL,
	id_profesora_cobra integer NULL,	-- solo EFECTIVO
	rendido boolean NOT NULL,
	fecha_rendicion timestamp without time zone NULL,
	id_usuario_confirma integer NULL,
	fecha_confirmacion timestamp without time zone NULL,
	motivo_rechazo varchar(255) NULL,	-- obligatorio si RECHAZADO
	observaciones varchar(255) NULL
)
;

CREATE TABLE parametros_sistema
(
	clave varchar(50) NOT NULL,	-- ej. DIAS_AVISO_VENCIMIENTO
	valor varchar(100) NOT NULL,
	tipo_dato varchar(8) NOT NULL,
	descripcion varchar(150) NULL,
	fecha_actualizacion timestamp without time zone NOT NULL
)
;

CREATE TABLE permisos
(
	id_permiso serial NOT NULL,
	codigo varchar(50) NOT NULL,	-- ej. PAGOS_CONFIRMAR
	modulo varchar(30) NOT NULL,
	descripcion varchar(150) NULL
)
;

CREATE TABLE plan_precios
(
	id_plan_precio serial NOT NULL,
	id_plan integer NOT NULL,
	precio NUMERIC(10,2) NOT NULL,	-- > 0
	fecha_vigencia_desde date NOT NULL,
	fecha_vigencia_hasta date NULL	-- NULL = vigente
)
;

CREATE TABLE planes
(
	id_plan serial NOT NULL,
	tipo varchar(12) NOT NULL,
	nombre varchar(40) NOT NULL,
	descripcion varchar(255) NULL,
	clases_por_semana smallint NULL,	-- 1..7; NULL si CLASE_SUELTA
	dias_gracia smallint NOT NULL,	-- >= 0; 0 si CLASE_SUELTA
	id_actividad_exclusiva integer NULL,	-- ej. Plan Kids
	profesora_unica boolean NOT NULL,
	fecha_alta date NOT NULL,
	fecha_baja date NULL
)
;

CREATE TABLE profesoras
(
	id_profesora serial NOT NULL,
	id_usuario integer NOT NULL,
	especialidad varchar(80) NULL,
	fecha_alta date NOT NULL,
	fecha_baja date NULL
)
;

CREATE TABLE promocion_planes
(
	id_promocion integer NOT NULL,
	id_plan integer NOT NULL
)
;

CREATE TABLE promociones
(
	id_promocion serial NOT NULL,
	codigo varchar(20) NOT NULL,
	nombre varchar(60) NOT NULL,
	tipo_descuento varchar(10) NOT NULL,
	valor NUMERIC(10,2) NOT NULL,	-- > 0; <= 100 si PORCENTAJE
	fecha_desde date NOT NULL,
	fecha_hasta date NOT NULL,	-- >= fecha_desde
	activo boolean NOT NULL
)
;

CREATE TABLE registros_progreso
(
	id_registro serial NOT NULL,
	id_alumno integer NOT NULL,
	id_profesora integer NOT NULL,
	fecha date NOT NULL,
	observaciones varchar(500) NULL
)
;

CREATE TABLE rol_permisos
(
	id_rol integer NOT NULL,
	id_permiso integer NOT NULL,
	fecha_asignacion timestamp without time zone NOT NULL
)
;

CREATE TABLE roles
(
	id_rol serial NOT NULL,
	codigo varchar(11) NOT NULL,	-- valores codigo: PROPIETARIA/PROFESORA/ALUMNO/TUTOR
	nombre varchar(40) NOT NULL,
	descripcion varchar(150) NULL
)
;

CREATE TABLE rutina_ejercicios
(
	id_ejercicio serial NOT NULL,
	id_rutina integer NOT NULL,
	orden smallint NOT NULL,	-- > 0
	nombre_ejercicio varchar(80) NOT NULL,
	series smallint NOT NULL,	-- > 0
	repeticiones varchar(20) NOT NULL,	-- texto libre: '12-15','AMRAP','30 seg'
	peso_sugerido varchar(20) NULL,	-- texto libre: '5kg','corporal'
	observaciones varchar(255) NULL
)
;

CREATE TABLE rutinas
(
	id_rutina serial NOT NULL,
	id_alumno integer NOT NULL,
	id_profesora integer NOT NULL,
	nombre varchar(60) NOT NULL,
	fecha_desde date NOT NULL,
	fecha_hasta date NULL,
	contenido text NOT NULL,
	observaciones varchar(500) NULL
)
;

CREATE TABLE suplencias
(
	id_clase integer NOT NULL,
	id_prof_ausente integer NOT NULL,
	motivo varchar(255) NULL,
	fecha_registro timestamp without time zone NOT NULL,
	id_usuario_registra integer NOT NULL
)
;

CREATE TABLE tarifas_honorario
(
	id_tarifa serial NOT NULL,
	id_profesora integer NOT NULL,
	concepto varchar(40) NOT NULL,
	id_plan integer NULL,	-- NULL = aplica a todos los planes
	tipo_valor varchar(10) NOT NULL,
	valor NUMERIC(10,2) NOT NULL,	-- > 0; <= 100 si PORCENTAJE
	fecha_vigencia_desde date NOT NULL,
	fecha_vigencia_hasta date NULL	-- NULL = vigente
)
;

CREATE TABLE tipos_medida
(
	id_tipo_medida serial NOT NULL,
	codigo varchar(20) NOT NULL,	-- ej. PESO, CINTURA
	unidad varchar(10) NOT NULL	-- ej. kg, cm
)
;

CREATE TABLE usuario_roles
(
	id_usuario integer NOT NULL,
	id_rol integer NOT NULL,
	fecha_asignacion timestamp without time zone NOT NULL
)
;

CREATE TABLE usuarios
(
	id_usuario serial NOT NULL,
	google_id varchar(255) NULL,	-- NULL hasta el 1er login; NULL en menores
	email varchar(120) NULL,	-- NULL en menores a cargo de tutor
	nombre varchar(60) NOT NULL,
	apellido varchar(60) NOT NULL,
	dni varchar(10) NULL,	-- solo digitos
	telefono varchar(20) NULL,
	fecha_nacimiento date NOT NULL,
	direccion varchar(120) NULL,
	estado varchar(8) NOT NULL,	-- valores: ACTIVO/INACTIVO
	fecha_alta timestamp without time zone NOT NULL,
	fecha_actualizacion timestamp without time zone NOT NULL
)
;

