/* Create Table Comments, Sequences for Autonumber Columns */

COMMENT ON TABLE actividades
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Unicidad: UK(codigo) || Reglas: cupo_maximo IS NULL OR cupo_maximo > 0 | modalidad <> ''PERSONALIZADA'' OR cupo_maximo IS NOT NULL | modalidad IN (GRUPAL,PERSONALIZADA)'
;

COMMENT ON COLUMN actividades.cupo_maximo
	IS '> 0; obligatorio si PERSONALIZADA'
;

COMMENT ON COLUMN actividades.requiere_medidas
	IS 'default false; peso y talla al pre-inscribir'
;

 

COMMENT ON TABLE alumno_insignias
	IS 'Area de negocio: NOTIFICACIONES E INSIGNIAS'
;

COMMENT ON TABLE alumnos
	IS 'Area de negocio: PERSONAS DEL NEGOCIO Unicidad: UK(id_usuario) || Reglas: estado IN (ACTIVO,INACTIVO,BAJA)'
;

COMMENT ON COLUMN alumnos.id_usuario_responsable
	IS 'tutor; obligatorio si es menor'
;

COMMENT ON COLUMN alumnos.apto_medico
	IS 'default false'
;

 

COMMENT ON TABLE asistencias
	IS 'Area de negocio: INSCRIPCIONES Y CLASES'
;

COMMENT ON COLUMN asistencias.id_usuario_registra
	IS 'NULL si lo registro el cierre automatico'
;

 

COMMENT ON TABLE clases
	IS 'Area de negocio: INSCRIPCIONES Y CLASES Unicidad: UK(id_horario,fecha_clase) || Reglas: estado IN (PROGRAMADA,DICTADA,CANCELADA)'
;

 

 

COMMENT ON TABLE cuotas
	IS 'Area de negocio: CUOTAS Y PAGOS Unicidad: UK(id_inscripcion,numero_cuota) || Reglas: numero_cuota >= 1 | monto >= 0'
;

COMMENT ON COLUMN cuotas.numero_cuota
	IS '>= 1'
;

COMMENT ON COLUMN cuotas.monto
	IS '>= 0'
;

 

COMMENT ON TABLE horarios
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Reglas: dia_semana BETWEEN 1 AND 7 | hora_fin > hora_inicio | cupo_maximo IS NULL OR cupo_maximo > 0'
;

COMMENT ON COLUMN horarios.dia_semana
	IS '1=Lun .. 7=Dom'
;

COMMENT ON COLUMN horarios.hora_fin
	IS '> hora_inicio'
;

COMMENT ON COLUMN horarios.cupo_maximo
	IS '> 0; NULL = toma el de la actividad'
;

 

COMMENT ON TABLE inscripcion_horarios
	IS 'Area de negocio: INSCRIPCIONES Y CLASES'
;

COMMENT ON TABLE inscripciones
	IS 'Area de negocio: INSCRIPCIONES Y CLASES Reglas: estado <> ''BAJA'' OR motivo_baja IS NOT NULL | estado IN (PREINSCRIPTA,ACTIVA,BAJA) | motivo_baja IN (ABANDONO,MUDANZA,SALUD,ECONOMICO,CAMBIO_PLAN,OTRO)'
;

COMMENT ON COLUMN inscripciones.id_profesora
	IS 'profesora a cargo'
;

COMMENT ON COLUMN inscripciones.sin_cargo
	IS 'true: profesora que entrena; no genera honorarios'
;

COMMENT ON COLUMN inscripciones.motivo_baja
	IS 'obligatorio si BAJA'
;

 

COMMENT ON TABLE insignias
	IS 'Area de negocio: NOTIFICACIONES E INSIGNIAS Unicidad: UK(codigo) || Reglas: valor_umbral > 0 | tipo_criterio IN (RACHA,ASISTENCIAS_TOTALES)'
;

COMMENT ON COLUMN insignias.valor_umbral
	IS '> 0'
;

 

COMMENT ON TABLE liquidacion_detalles
	IS 'Area de negocio: HONORARIOS Reglas: concepto <> ''ALUMNO_A_CARGO'' OR id_inscripcion IS NOT NULL | concepto = ''ALUMNO_A_CARGO'' OR id_clase IS NOT NULL | concepto <> ''DESCUENTO_AUSENCIA'' OR monto < 0 | concepto IN (ALUMNO_A_CARGO,CLASE_SUPLIDA,DESCUENTO_AUSENCIA)'
;

COMMENT ON COLUMN liquidacion_detalles.id_inscripcion
	IS 'obligatorio si ALUMNO_A_CARGO'
;

COMMENT ON COLUMN liquidacion_detalles.id_clase
	IS 'obligatorio si CLASE_SUPLIDA / DESCUENTO_AUSENCIA'
;

COMMENT ON COLUMN liquidacion_detalles.monto
	IS '< 0 si DESCUENTO_AUSENCIA'
;

 

COMMENT ON TABLE liquidaciones
	IS 'Area de negocio: HONORARIOS Reglas: periodo_hasta > periodo_desde | estado IN (BORRADOR,CERRADA,PAGADA)'
;

COMMENT ON COLUMN liquidaciones.periodo_hasta
	IS '> periodo_desde'
;

 

COMMENT ON TABLE medidas_corporales
	IS 'Area de negocio: RUTINAS Y PROGRESO Reglas: valor > 0'
;

COMMENT ON COLUMN medidas_corporales.valor
	IS '> 0'
;

COMMENT ON TABLE notificaciones
	IS 'Area de negocio: NOTIFICACIONES E INSIGNIAS Reglas: tipo IN (CUOTA_POR_VENCER,CUOTA_VENCIDA,RESUMEN_DIARIO,BIENVENIDA,CLASE_CANCELADA) | estado_envio IN (PENDIENTE,ENVIADA,ERROR)'
;

COMMENT ON COLUMN notificaciones.id_cuota
	IS 'solo avisos de cuota'
;

 

COMMENT ON TABLE pagos
	IS 'Area de negocio: CUOTAS Y PAGOS Reglas: monto > 0 | estado <> ''RECHAZADO'' OR motivo_rechazo IS NOT NULL | forma_pago = ''EFECTIVO'' OR id_profesora_cobra IS NULL | forma_pago IN (EFECTIVO,TRANSFERENCIA) | estado IN (PENDIENTE,CONFIRMADO,RECHAZADO)'
;

COMMENT ON COLUMN pagos.monto
	IS '> 0'
;

COMMENT ON COLUMN pagos.titular_cuenta_origen
	IS 'solo TRANSFERENCIA'
;

COMMENT ON COLUMN pagos.fecha_hora_transferencia
	IS 'solo TRANSFERENCIA'
;

COMMENT ON COLUMN pagos.id_profesora_cobra
	IS 'solo EFECTIVO'
;

COMMENT ON COLUMN pagos.motivo_rechazo
	IS 'obligatorio si RECHAZADO'
;

 

 

 

COMMENT ON TABLE parametros_sistema
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Reglas: tipo_dato IN (ENTERO,DECIMAL,TEXTO,BOOLEANO)'
;

COMMENT ON COLUMN parametros_sistema.clave
	IS 'ej. DIAS_AVISO_VENCIMIENTO'
;

COMMENT ON TABLE permisos
	IS 'Area de negocio: IDENTIDAD Y ACCESO Unicidad: UK(codigo)'
;

COMMENT ON COLUMN permisos.codigo
	IS 'ej. PAGOS_CONFIRMAR'
;

 

COMMENT ON TABLE plan_precios
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Reglas: precio > 0 | fecha_vigencia_hasta IS NULL OR fecha_vigencia_hasta >= fecha_vigencia_desde'
;

COMMENT ON COLUMN plan_precios.precio
	IS '> 0'
;

COMMENT ON COLUMN plan_precios.fecha_vigencia_hasta
	IS 'NULL = vigente'
;

 

COMMENT ON TABLE planes
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Reglas: clases_por_semana IS NULL OR clases_por_semana BETWEEN 1 AND 7 | dias_gracia >= 0 | tipo <> ''CLASE_SUELTA'' OR (clases_por_semana IS NULL AND dias_gracia = 0) | tipo IN (MENSUAL,CLASE_SUELTA)'
;

COMMENT ON COLUMN planes.clases_por_semana
	IS '1..7; NULL si CLASE_SUELTA'
;

COMMENT ON COLUMN planes.dias_gracia
	IS '>= 0; 0 si CLASE_SUELTA'
;

COMMENT ON COLUMN planes.id_actividad_exclusiva
	IS 'ej. Plan Kids'
;

 

 

COMMENT ON TABLE profesoras
	IS 'Area de negocio: PERSONAS DEL NEGOCIO Unicidad: UK(id_usuario)'
;

 

COMMENT ON TABLE promocion_planes
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO'
;

COMMENT ON TABLE promociones
	IS 'Area de negocio: SERVICIO ENTRENAMIENTO Unicidad: UK(codigo) || Reglas: valor > 0 | tipo_descuento <> ''PORCENTAJE'' OR valor <= 100 | fecha_hasta >= fecha_desde | tipo_descuento IN (PORCENTAJE,MONTO_FIJO)'
;

COMMENT ON COLUMN promociones.valor
	IS '> 0; <= 100 si PORCENTAJE'
;

COMMENT ON COLUMN promociones.fecha_hasta
	IS '>= fecha_desde'
;

 

COMMENT ON TABLE registros_progreso
	IS 'Area de negocio: RUTINAS Y PROGRESO'
;

 

COMMENT ON TABLE rol_permisos
	IS 'Area de negocio: IDENTIDAD Y ACCESO'
;

COMMENT ON TABLE roles
	IS 'Area de negocio: IDENTIDAD Y ACCESO Unicidad: UK(codigo) || Reglas: codigo IN (PROPIETARIA,PROFESORA,ALUMNO,TUTOR)'
;

COMMENT ON COLUMN roles.codigo
	IS 'valores codigo: PROPIETARIA/PROFESORA/ALUMNO/TUTOR'
;

 

COMMENT ON TABLE rutina_ejercicios
	IS 'Area de negocio: RUTINAS Y PROGRESO Reglas: orden > 0 | series > 0'
;

COMMENT ON COLUMN rutina_ejercicios.orden
	IS '> 0'
;

COMMENT ON COLUMN rutina_ejercicios.series
	IS '> 0'
;

COMMENT ON COLUMN rutina_ejercicios.repeticiones
	IS 'texto libre: ''12-15'',''AMRAP'',''30 seg'''
;

COMMENT ON COLUMN rutina_ejercicios.peso_sugerido
	IS 'texto libre: ''5kg'',''corporal'''
;

 

COMMENT ON TABLE rutinas
	IS 'Area de negocio: RUTINAS Y PROGRESO'
;

 

COMMENT ON TABLE suplencias
	IS 'Area de negocio: INSCRIPCIONES Y CLASES'
;

 

 

COMMENT ON TABLE tarifas_honorario
	IS 'Area de negocio: HONORARIOS Reglas: valor > 0 | tipo_valor <> ''PORCENTAJE'' OR valor <= 100 | concepto = ''ALUMNO_A_CARGO'' OR id_plan IS NULL | fecha_vigencia_hasta IS NULL OR fecha_vigencia_hasta >= fecha_vigencia_desde | concepto IN (ALUMNO_A_CARGO,HORA_SUPLENCIA) | tipo_valor IN (PORCENTAJE,MONTO_FIJO)'
;

COMMENT ON COLUMN tarifas_honorario.id_plan
	IS 'NULL = aplica a todos los planes'
;

COMMENT ON COLUMN tarifas_honorario.valor
	IS '> 0; <= 100 si PORCENTAJE'
;

COMMENT ON COLUMN tarifas_honorario.fecha_vigencia_hasta
	IS 'NULL = vigente'
;

 

COMMENT ON TABLE tipos_medida
	IS 'Area de negocio: RUTINAS Y PROGRESO Unicidad: UK(codigo)'
;

COMMENT ON COLUMN tipos_medida.codigo
	IS 'ej. PESO, CINTURA'
;

COMMENT ON COLUMN tipos_medida.unidad
	IS 'ej. kg, cm'
;

 

COMMENT ON TABLE usuario_roles
	IS 'Area de negocio: IDENTIDAD Y ACCESO'
;

COMMENT ON TABLE usuarios
	IS 'Area de negocio: IDENTIDAD Y ACCESO Unicidad: UK(google_id); UK(email); UK(dni) || Reglas: estado IN (ACTIVO,INACTIVO)'
;

COMMENT ON COLUMN usuarios.google_id
	IS 'NULL hasta el 1er login; NULL en menores'
;

COMMENT ON COLUMN usuarios.email
	IS 'NULL en menores a cargo de tutor'
;

COMMENT ON COLUMN usuarios.dni
	IS 'solo digitos'
;

COMMENT ON COLUMN usuarios.estado
	IS 'valores: ACTIVO/INACTIVO'
;

 

/* ===== Correcciones de FK agregadas manualmente =====
   El generador de DDL de EA adivina el nombre de columna por
   convencion (id_ + tabla) y no reconocio bien estas 11 relaciones,
   porque en el modelo real la columna tiene un nombre mas
   especifico. Ademas, al no encontrar el nombre, fabricaba una
   columna extra invalida en el CREATE TABLE (ya eliminada arriba). */

ALTER TABLE clases ADD CONSTRAINT "FK_clases_prof_dictante"
	FOREIGN KEY (id_prof_dictante) REFERENCES profesoras (id_profesora)
;

ALTER TABLE pagos ADD CONSTRAINT "FK_pagos_usuario_registra"
	FOREIGN KEY (id_usuario_registra) REFERENCES usuarios (id_usuario)
;

ALTER TABLE pagos ADD CONSTRAINT "FK_pagos_usuario_confirma"
	FOREIGN KEY (id_usuario_confirma) REFERENCES usuarios (id_usuario)
;

ALTER TABLE pagos ADD CONSTRAINT "FK_pagos_profesora_cobra"
	FOREIGN KEY (id_profesora_cobra) REFERENCES profesoras (id_profesora)
;

ALTER TABLE planes ADD CONSTRAINT "FK_planes_actividad_exclusiva"
	FOREIGN KEY (id_actividad_exclusiva) REFERENCES actividades (id_actividad)
;

ALTER TABLE suplencias ADD CONSTRAINT "FK_suplencias_prof_ausente"
	FOREIGN KEY (id_prof_ausente) REFERENCES profesoras (id_profesora)
;

ALTER TABLE suplencias ADD CONSTRAINT "FK_suplencias_usuario_registra"
	FOREIGN KEY (id_usuario_registra) REFERENCES usuarios (id_usuario)
;

ALTER TABLE suplencias ADD CONSTRAINT "FK_suplencias_clases"
	FOREIGN KEY (id_clase) REFERENCES clases (id_clase)
;

ALTER TABLE alumnos ADD CONSTRAINT "FK_alumnos_usuario_responsable"
	FOREIGN KEY (id_usuario_responsable) REFERENCES usuarios (id_usuario)
;

ALTER TABLE usuario_roles ADD CONSTRAINT "FK_usuario_roles_usuarios"
	FOREIGN KEY (id_usuario) REFERENCES usuarios (id_usuario)
;

ALTER TABLE asistencias ADD CONSTRAINT "FK_asistencias_usuario_registra"
	FOREIGN KEY (id_usuario_registra) REFERENCES usuarios (id_usuario)
;

/* ===== CHECK constraints (dominio y reglas de negocio) =====
   El generador de DDL de EA no exporta estos constraints (limitacion
   de esta version), se agregan aca con las mismas expresiones ya
   validadas contra PostgreSQL real. */

ALTER TABLE usuarios ADD CONSTRAINT "ck_usuarios_estado" CHECK (estado IN ('ACTIVO', 'INACTIVO'));
ALTER TABLE roles ADD CONSTRAINT "ck_roles_codigo" CHECK (codigo IN ('PROPIETARIA', 'PROFESORA', 'ALUMNO', 'TUTOR'));
ALTER TABLE actividades ADD CONSTRAINT "ck_actividades_modalidad" CHECK (modalidad IN ('GRUPAL', 'PERSONALIZADA'));
ALTER TABLE actividades ADD CONSTRAINT "ck_actividades_x1" CHECK (cupo_maximo IS NULL OR cupo_maximo > 0);
ALTER TABLE actividades ADD CONSTRAINT "ck_actividades_x2" CHECK (modalidad <> 'PERSONALIZADA' OR cupo_maximo IS NOT NULL);
ALTER TABLE horarios ADD CONSTRAINT "ck_horarios_x1" CHECK (dia_semana BETWEEN 1 AND 7);
ALTER TABLE horarios ADD CONSTRAINT "ck_horarios_x2" CHECK (hora_fin > hora_inicio);
ALTER TABLE horarios ADD CONSTRAINT "ck_horarios_x3" CHECK (cupo_maximo IS NULL OR cupo_maximo > 0);
ALTER TABLE planes ADD CONSTRAINT "ck_planes_tipo" CHECK (tipo IN ('MENSUAL', 'CLASE_SUELTA'));
ALTER TABLE planes ADD CONSTRAINT "ck_planes_x1" CHECK (clases_por_semana IS NULL OR clases_por_semana BETWEEN 1 AND 7);
ALTER TABLE planes ADD CONSTRAINT "ck_planes_x2" CHECK (dias_gracia >= 0);
ALTER TABLE planes ADD CONSTRAINT "ck_planes_x3" CHECK (tipo <> 'CLASE_SUELTA' OR (clases_por_semana IS NULL AND dias_gracia = 0));
ALTER TABLE plan_precios ADD CONSTRAINT "ck_plan_precios_x1" CHECK (precio > 0);
ALTER TABLE plan_precios ADD CONSTRAINT "ck_plan_precios_x2" CHECK (fecha_vigencia_hasta IS NULL OR fecha_vigencia_hasta >= fecha_vigencia_desde);
ALTER TABLE promociones ADD CONSTRAINT "ck_promociones_tipo_descuento" CHECK (tipo_descuento IN ('PORCENTAJE', 'MONTO_FIJO'));
ALTER TABLE promociones ADD CONSTRAINT "ck_promociones_x1" CHECK (valor > 0);
ALTER TABLE promociones ADD CONSTRAINT "ck_promociones_x2" CHECK (tipo_descuento <> 'PORCENTAJE' OR valor <= 100);
ALTER TABLE promociones ADD CONSTRAINT "ck_promociones_x3" CHECK (fecha_hasta >= fecha_desde);
ALTER TABLE parametros_sistema ADD CONSTRAINT "ck_parametros_sistema_tipo_dato" CHECK (tipo_dato IN ('ENTERO', 'DECIMAL', 'TEXTO', 'BOOLEANO'));
ALTER TABLE alumnos ADD CONSTRAINT "ck_alumnos_estado" CHECK (estado IN ('ACTIVO', 'INACTIVO', 'BAJA'));
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_concepto" CHECK (concepto IN ('ALUMNO_A_CARGO', 'HORA_SUPLENCIA'));
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_tipo_valor" CHECK (tipo_valor IN ('PORCENTAJE', 'MONTO_FIJO'));
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_x1" CHECK (valor > 0);
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_x2" CHECK (tipo_valor <> 'PORCENTAJE' OR valor <= 100);
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_x3" CHECK (concepto = 'ALUMNO_A_CARGO' OR id_plan IS NULL);
ALTER TABLE tarifas_honorario ADD CONSTRAINT "ck_tarifas_honorario_x4" CHECK (fecha_vigencia_hasta IS NULL OR fecha_vigencia_hasta >= fecha_vigencia_desde);
ALTER TABLE liquidaciones ADD CONSTRAINT "ck_liquidaciones_estado" CHECK (estado IN ('BORRADOR', 'CERRADA', 'PAGADA'));
ALTER TABLE liquidaciones ADD CONSTRAINT "ck_liquidaciones_x1" CHECK (periodo_hasta > periodo_desde);
ALTER TABLE liquidacion_detalles ADD CONSTRAINT "ck_liquidacion_detalles_concepto" CHECK (concepto IN ('ALUMNO_A_CARGO', 'CLASE_SUPLIDA', 'DESCUENTO_AUSENCIA'));
ALTER TABLE liquidacion_detalles ADD CONSTRAINT "ck_liquidacion_detalles_x1" CHECK (concepto <> 'ALUMNO_A_CARGO' OR id_inscripcion IS NOT NULL);
ALTER TABLE liquidacion_detalles ADD CONSTRAINT "ck_liquidacion_detalles_x2" CHECK (concepto = 'ALUMNO_A_CARGO' OR id_clase IS NOT NULL);
ALTER TABLE liquidacion_detalles ADD CONSTRAINT "ck_liquidacion_detalles_x3" CHECK (concepto <> 'DESCUENTO_AUSENCIA' OR monto < 0);
ALTER TABLE inscripciones ADD CONSTRAINT "ck_inscripciones_estado" CHECK (estado IN ('PREINSCRIPTA', 'ACTIVA', 'BAJA'));
ALTER TABLE inscripciones ADD CONSTRAINT "ck_inscripciones_motivo_baja" CHECK (motivo_baja IN ('ABANDONO', 'MUDANZA', 'SALUD', 'ECONOMICO', 'CAMBIO_PLAN', 'OTRO'));
ALTER TABLE inscripciones ADD CONSTRAINT "ck_inscripciones_x1" CHECK (estado <> 'BAJA' OR motivo_baja IS NOT NULL);
ALTER TABLE clases ADD CONSTRAINT "ck_clases_estado" CHECK (estado IN ('PROGRAMADA', 'DICTADA', 'CANCELADA'));
ALTER TABLE cuotas ADD CONSTRAINT "ck_cuotas_x1" CHECK (numero_cuota >= 1);
ALTER TABLE cuotas ADD CONSTRAINT "ck_cuotas_x2" CHECK (monto >= 0);
ALTER TABLE pagos ADD CONSTRAINT "ck_pagos_forma_pago" CHECK (forma_pago IN ('EFECTIVO', 'TRANSFERENCIA'));
ALTER TABLE pagos ADD CONSTRAINT "ck_pagos_estado" CHECK (estado IN ('PENDIENTE', 'CONFIRMADO', 'RECHAZADO'));
ALTER TABLE pagos ADD CONSTRAINT "ck_pagos_x1" CHECK (monto > 0);
ALTER TABLE pagos ADD CONSTRAINT "ck_pagos_x2" CHECK (estado <> 'RECHAZADO' OR motivo_rechazo IS NOT NULL);
ALTER TABLE pagos ADD CONSTRAINT "ck_pagos_x3" CHECK (forma_pago = 'EFECTIVO' OR id_profesora_cobra IS NULL);
ALTER TABLE rutina_ejercicios ADD CONSTRAINT "ck_rutina_ejercicios_x1" CHECK (orden > 0);
ALTER TABLE rutina_ejercicios ADD CONSTRAINT "ck_rutina_ejercicios_x2" CHECK (series > 0);
ALTER TABLE medidas_corporales ADD CONSTRAINT "ck_medidas_corporales_x1" CHECK (valor > 0);
ALTER TABLE notificaciones ADD CONSTRAINT "ck_notificaciones_tipo" CHECK (tipo IN ('CUOTA_POR_VENCER', 'CUOTA_VENCIDA', 'RESUMEN_DIARIO', 'BIENVENIDA', 'CLASE_CANCELADA'));
ALTER TABLE notificaciones ADD CONSTRAINT "ck_notificaciones_estado_envio" CHECK (estado_envio IN ('PENDIENTE', 'ENVIADA', 'ERROR'));
ALTER TABLE insignias ADD CONSTRAINT "ck_insignias_tipo_criterio" CHECK (tipo_criterio IN ('RACHA', 'ASISTENCIAS_TOTALES'));
ALTER TABLE insignias ADD CONSTRAINT "ck_insignias_x1" CHECK (valor_umbral > 0);